# test/test_web.sh — XML + CSS dashboard (cgi-bin/web.sh, cgi-bin/act.sh)
#
# The panel is an XML document styled by one CSS file, both generated by the
# same CGI. No HTML document, no client-side script, no external asset. These
# tests pin the properties that make that choice defensible:
#
#   * the bytes are well-formed XML and reference exactly one stylesheet
#   * the stylesheet uses attribute/element selectors only — a `.class`
#     selector silently never matches in an XML document, so one slipping in
#     would be an invisible regression
#   * the secret never appears in a URL or in a response body
#   * the only writable channel (act.sh) needs a live nonce and can only
#     pause/resume the refresh flag

_web_get() {
	( cd "$(dirname "$0")/.." && REQUEST_METHOD=GET QUERY_STRING="$1" \
		sh ./cgi-bin/web.sh 2>/dev/null </dev/null | tr -d '\r' )
}

_web_get_sec() {
	# $1=secret  $2=cookie-value  $3=query
	( cd "$(dirname "$0")/.." && WEBHOOK_SECRET="$1" HTTP_COOKIE="ayu=$2" \
		REQUEST_METHOD=GET QUERY_STRING="$3" \
		sh ./cgi-bin/web.sh 2>/dev/null </dev/null | tr -d '\r' )
}

_web_post() {
	# $1=secret  $2=form body
	( cd "$(dirname "$0")/.." && printf '%s' "$2" | \
		WEBHOOK_SECRET="$1" REQUEST_METHOD=POST CONTENT_LENGTH="${#2}" \
		QUERY_STRING="" sh ./cgi-bin/web.sh 2>/dev/null | tr -d '\r' )
}

_web_act() {
	# $1=query
	( cd "$(dirname "$0")/.." && QUERY_STRING="$1" sh ./cgi-bin/act.sh 2>/dev/null </dev/null | tr -d '\r' )
}

_web_sha() {
	printf '%s' "$1" | sha256sum | awk '{print $1}'
}

# _web_body <output> — strip header block, keep the document
_web_body() {
	printf '%s' "$1" | sed '1,/^\r*$/d'
}

test_web_document_is_xml() {
	_out="$(_web_get 'page=all')"
	assert_contains "$_out" 'Content-Type: text/xml' "overview is served as XML"
	assert_contains "$_out" '<?xml version="1.0" encoding="UTF-8"?>' "document has an XML declaration"
	assert_contains "$_out" '<?xml-stylesheet type="text/css"' "document references a CSS stylesheet PI"
	assert_contains "$_out" '</panel>' "document closes its root element"
	assert_eq "$(printf '%s' "$_out" | grep -c '^<panel>$')" "1" "exactly one root element"
}

test_web_has_no_html_and_no_script() {
	_out="$(_web_get 'page=all')"
	assert_not_contains "$_out" '<!DOCTYPE html>' "no HTML doctype"
	assert_not_contains "$_out" '<html' "no html element"
	assert_not_contains "$_out" '<script' "no script element"
	assert_not_contains "$_out" '<body' "no body element"
	assert_not_contains "$_out" 'app.js' "no client bundle"
	assert_eq "$(ls index.html webui/index.html 2>/dev/null | wc -l | tr -d ' ')" \
		"0" "no index.html anywhere in the tree"
}

test_web_xml_is_wellformed() {
	# Every '&' must belong to an entity; a bare one makes the document a parse
	# error in the browser, which would show a yellow error page instead of the
	# panel. Cheap proxy for a real parser.
	_body="$(_web_body "$(_web_get 'page=all&logs=bot&lines=5')")"
	_bare="$(printf '%s' "$_body" | sed \
		-e 's/&amp;//g' -e 's/&lt;//g' -e 's/&gt;//g' \
		-e 's/&quot;//g' -e 's/&apos;//g' -e 's/&#[0-9]*;//g' | grep -c '&')"
	assert_eq "$_bare" "0" "no unescaped ampersand in the document"
	assert_eq "$(printf '%s' "$_body" | grep -c '<!--')" "0" "no comment (unsafe with --)"
}

test_web_stylesheet_uses_attribute_selectors() {
	_out="$(_web_get_sec 's3cr3t' "$(_web_sha 's3cr3t')" 'css=1')"
	assert_contains "$_out" 'Content-Type: text/css' "stylesheet is served as CSS"
	assert_contains "$_out" 'face[class="top"]' "3D faces keyed by attribute selector"
	assert_contains "$_out" '@keyframes spin' "3D rotation is a CSS animation"
	assert_contains "$_out" 'transform-style: preserve-3d' "3D needs preserve-3d on the rotor"
	assert_contains "$_out" ':active' "pads drive commands from :active"
	assert_contains "$_out" 'act.sh?n=' "command URL carries a nonce"
	# A `.foo` selector would compile fine and never match in XML — exactly the
	# silent regression these tests exist for.
	_classes="$(printf '%s' "$_out" | grep -cE '^[a-z]+[.][a-z]')"
	assert_eq "$_classes" "0" "no bare .class selectors in the sheet"
}

test_web_stylesheet_refused_without_cookie() {
	_out="$(_web_get_sec 's3cr3t' '' 'css=1')"
	assert_contains "$_out" 'Content-Type: text/css' "refusal still answers CSS"
	assert_not_contains "$_out" 'act.sh' "unauthenticated caller never sees a command URL"
	assert_not_contains "$_out" '@keyframes' "unauthenticated caller gets no panel sheet"
}

test_web_every_section_renders() {
	_out="$(_web_get 'page=all')"
	assert_contains "$_out" '运行时长' "headline uptime"
	assert_contains "$_out" '消息映射' "storage card"
	assert_contains "$_out" '转发映射' "forwarding card"
	assert_contains "$_out" '日志 · bot.log' "log card"
	assert_contains "$_out" '运行配置' "config card"
	assert_contains "$_out" 'Refresh: 5' "panel asks for 5s refresh via header"
	assert_contains "$_out" '<scene>' "3D scene present"
}

test_web_refresh_can_be_paused() {
	_state="$(dirname "$0")/../var/state"
	_act_cleanup() { rm -f "$_state/web-paused"; }
	_act_cleanup
	_nonce="$(printf '%s' "$(_web_get_sec 's3cr3t' "$(_web_sha 's3cr3t')" 'css=1')" \
		| sed -n 's#.*act\.sh?n=\([0-9a-f][0-9a-f]*\).*#\1#p' | head -1)"
	[ -n "$_nonce" ] && _PASS=$((_PASS + 1)) || { _FAIL=$((_FAIL + 1)); printf 'FAIL: stylesheet carries a nonce\n'; }

	_web_act "n=$_nonce&op=pause" >/dev/null
	[ -f "$_state/web-paused" ] && _PASS=$((_PASS + 1)) || { _FAIL=$((_FAIL + 1)); printf 'FAIL: pause creates the flag\n'; }
	_out="$(_web_get 'page=all')"
	assert_contains "$_out" 'Refresh: 30' "paused panel slows to a 30s safety refresh"
	assert_contains "$_out" '恢复自动刷新' "paused panel offers the resume pad"

	_web_act "n=$_nonce&op=resume" >/dev/null
	[ ! -f "$_state/web-paused" ] && _PASS=$((_PASS + 1)) || { _FAIL=$((_FAIL + 1)); printf 'FAIL: resume clears the flag\n'; }
	_out="$(_web_get 'page=all')"
	assert_contains "$_out" 'Refresh: 5' "resumed panel is back to 5s"
	_act_cleanup
}

test_web_act_rejects_unknown_nonce_and_op() {
	_state="$(dirname "$0")/../var/state"
	rm -f "$_state/web-paused"
	_out="$(_web_act 'n=deadbeefdeadbeef&op=pause')"
	assert_contains "$_out" 'Content-Type: image/gif' "rejection still answers a GIF"
	[ ! -f "$_state/web-paused" ] && _PASS=$((_PASS + 1)) || { _FAIL=$((_FAIL + 1)); printf 'FAIL: unknown nonce must not pause\n'; }
	_nonce="$(head -1 "$_state/web-nonce" 2>/dev/null | awk '{print $1}')"
	_web_act "n=$_nonce&op=restart" >/dev/null
	[ ! -f "$_state/web-paused" ] && _PASS=$((_PASS + 1)) || { _FAIL=$((_FAIL + 1)); printf 'FAIL: op allowlist rejects restart\n'; }
	rm -f "$_state/web-paused"
}

test_web_gate_hides_panel() {
	_out="$(_web_get_sec 'gate-secret' '' 'page=all')"
	assert_contains "$_out" 'Content-Type: text/xml' "gate is XML too"
	assert_contains "$_out" 'curl -s -X POST' "gate explains the out-of-band login"
	assert_not_contains "$_out" '消息映射' "gate never renders gauges"
	assert_not_contains "$_out" 'gate-secret' "gate never echoes the secret"
	assert_not_contains "$_out" '<input' "gate has no form control (XML has none)"
}

test_web_wrong_token_rejected() {
	_out="$(_web_post 'right-secret' 'token=wrong')"
	assert_contains "$_out" '密钥错误' "wrong token reports an error"
	assert_not_contains "$_out" 'Set-Cookie: ayu=' "wrong token sets no cookie"
}

test_web_login_sets_digest_cookie() {
	_out="$(_web_post 'right-secret' 'token=right-secret')"
	assert_contains "$_out" '303 See Other' "correct token redirects"
	assert_contains "$_out" "Set-Cookie: ayu=$(_web_sha 'right-secret')" "cookie carries sha256(secret)"
	assert_not_contains "$_out" 'token=right-secret' "secret is not echoed back"
}

test_web_cookie_auth() {
	_out="$(_web_get_sec 'right-secret' "$(_web_sha 'right-secret')" 'page=config')"
	assert_contains "$_out" '运行配置' "authed cookie renders the panel"
	_out="$(_web_get_sec 'right-secret' 'deadbeef' 'page=config')"
	assert_contains "$_out" 'curl -s -X POST' "wrong cookie falls back to the gate"
}

test_web_logout_drops_cookie() {
	_out="$(_web_get_sec 'right-secret' x 'logout=1')"
	assert_contains "$_out" '303 See Other' "logout redirects"
	assert_contains "$_out" 'Max-Age=0' "logout expires the cookie"
}

test_web_prod_without_secret_refuses() {
	_out="$( cd "$(dirname "$0")/.." && env -u QQBOT_WEBHOOK_TOKEN -u FNOS_WEBHOOK_TOKEN \
		AYU_ENV=prod WEBHOOK_SECRET= REQUEST_METHOD=GET QUERY_STRING='page=all' \
		sh ./cgi-bin/web.sh 2>/dev/null | tr -d '\r' )"
	assert_contains "$_out" '503 Service Unavailable' "prod without secret refuses to serve"
	assert_contains "$_out" 'Content-Type: text/xml' "refusal is XML as well"
	assert_contains "$_out" '面板拒绝提供服务' "refusal explains itself"
	assert_not_contains "$_out" '消息映射' "refusal page leaks no gauges"
}

test_web_document_is_xml
test_web_has_no_html_and_no_script
test_web_xml_is_wellformed
test_web_stylesheet_uses_attribute_selectors
test_web_stylesheet_refused_without_cookie
test_web_every_section_renders
test_web_refresh_can_be_paused
test_web_act_rejects_unknown_nonce_and_op
test_web_gate_hides_panel
test_web_wrong_token_rejected
test_web_login_sets_digest_cookie
test_web_cookie_auth
test_web_logout_drops_cookie
test_web_prod_without_secret_refuses
